    entries: ["chengyu-cy-106"],
    text: "居卫月余，灵公与夫人同车，宦者雍渠参乘，出，使孔子为次乘，招摇市过之。孔子曰：「吾未见好德如好色者也。」于是丑之，去卫，过曹。",
