    id: "chengyu-cy-126",
    title: "图穷匕见",
    entries: ["chengyu-cy-126"],
    text: "荆轲奉樊於期头函，而秦武阳奉地图匣，以次进。……轲既取图奉之，发图，图穷而匕首见。因左手把秦王之袖，而右手持匕首揕之。",
    translation: "荆轲捧着樊於期的头颅的匣子，秦舞阳捧着地图匣子，按次序上前。……荆轲取过地图献给秦王，展开地图，地图展到尽头，匕首就露了出来。于是左手抓住秦王的衣袖，右手拿起匕首刺他。",
