    title: "虚与委蛇",
    entries: ["chengyu-cy-152"],
    text: "壶子曰：「乡吾示之以未始出吾宗。吾与之虚而委蛇，不知其谁何，因以为弟靡，因以为波流，故逃也。」",
    translation: "壶子说：「刚才我显示给他看的是未曾出自我本真的道。我与他虚应求合、随顺应变，他弄不清我究竟是谁，因而把我当成随风倒、逐波流的人，所以逃走了。」",
