    text: "郢人垩慢其鼻端，若蝇翼，使匠石斫之。匠石运斤成风，听而斫之，尽垩而鼻不伤，郢人立不失容。",
    translation: "郢地有个人把白土涂在鼻尖上，薄得像苍蝇的翅膀，让匠石用斧子削它。匠石挥动斧子呼呼生风，随手削去，白土削尽而鼻子没有受伤，郢人站着也面不改色。",
