    id: "chengyu-cy-16",
    title: "罪己责躬",
    entries: ["chengyu-cy-16"],
    text: "尔万方有众，明听予一人诰。惟皇上帝，降衷于下民。若有恒性，克绥厥猷惟后。夏王灭德作威，以敷虐于尔万方百姓。……罪当朕躬，弗敢自赦，惟简在上帝之心。其尔万方有罪，在予一人；予一人有罪，无以尔万方。",
    translation: "你们四方众民，清楚地听我一人发布的告诫。伟大的上帝把善心降于下民。如有常性之人，能够安于自己的道义的，只有君主。夏王灭绝道德、逞施威虐，用来虐害你们四方百姓。……罪过应当由我一人承担，我不敢自我宽赦，只因上帝心中自会衡量。你们四方百姓如果有罪，罪在我一人；我一人有罪，不要牵连你们四方百姓。",
