    entries: ["chengyu-cy-180"],
    text: "吕不韦乃使其客人人著所闻，集论以为八览、六论、十二纪，二十余万言。以为备天地万物古今之事，号曰《吕氏春秋》。布咸阳市门，悬千金其上，延诸侯游士宾客有能增损一字者予千金。",
    translation: "吕不韦于是让他的门客人人写下所见所闻，汇集论著为八览、六论、十二纪，二十多万字。认为已经完备了天地万物古今之事，称作《吕氏春秋》。把它公布在咸阳城门上，在上面悬挂千金，邀请诸侯的游士宾客，有能增减一个字的就给他千金。",
