    translation: "凭您这样的所作所为，去追求您所想得到的，就像爬到树上去捉鱼一样。……爬到树上去捉鱼，虽然捉不到鱼，却没有后患；凭您这样的所作所为，去追求您所想得到的，尽心竭力去做，以后一定会有灾祸。",
