    entries: ["chengyu-cy-21"],
    text: "沛公入秦宫，宫室帷帐狗马重宝妇女以千数，意欲留居之。樊哙谏沛公出舍，沛公不听。良曰：「夫秦为无道，故沛公得至此。夫为天下除残贼，宜缟素为资。今始入秦，即安其乐，此所谓『助桀为虐』。」",
    translation: "沛公进入秦朝宫室，看见宫室、帷帐、狗马、重宝、妇女数以千计，就想留下来住在里面。樊哙劝他出去住，沛公不听。张良说：「正因为秦朝无道，沛公您才能到这里来。为天下除去残暴的贼人，应当以朴素为本。如今刚进秦宫，就安于享乐，这正是人们所说的『帮助夏桀做暴虐的事』。」",
