    title: "杞人忧天",
    entries: ["chengyu-cy-214"],
    text: "杞国有人忧天地崩坠，身亡所寄，废寝食者。又有忧彼之所忧者，因往晓之。……其人曰：「奈地坏何？」晓之者曰：「地积块耳，充塞四虚，亡处亡块。若躇步跐蹈，终日在地上行止，奈何忧其坏？」其人舍然大喜。",
    translation: "杞国有个人担心天会塌下来、地会陷下去，自己无处安身，愁得吃不下饭、睡不着觉。又有一个人为他的忧愁而担忧，就去开导他。……那人说：「地陷下去怎么办呢？」开导他的人说：「地是堆积起来的土块，充满四方空间，没有一处没有土块。你行走踩踏，整天在地上活动，为什么要担心它会陷下去呢？」那人于是放心高兴起来。",
