    translation: "纣王天资聪敏，反应快，见闻广博；气力超过常人，能空手与猛兽搏斗；智慧足以拒绝劝谏，口才足以掩饰过错；向臣下夸耀自己的才能，向天下抬高自己的声名，认为谁都比不上自己。他喜好饮酒、放纵享乐，宠爱妇人。最爱妲己，凡事都听妲己的话。……他挖池子盛酒，把肉悬挂起来像树林，让男男女女赤身裸体，在其中互相追逐，作长夜的饮宴。",
