    text: "赵高欲为乱，恐群臣不听，乃先设验，持鹿献于二世，曰：「马也。」二世笑曰：「丞相误邪？谓鹿为马。」问左右，左右或默，或言马以阿顺赵高。或言鹿者，高因阴中诸言鹿者以法。后群臣皆畏高。",
