    title: "孺子可教",
    entries: ["chengyu-cy-237"],
    text: "父去里所，复还，曰：「孺子可教矣。后五日平明，与我会此。」",
    translation: "老人走了约一里路，又返回来，说：「你这小子可以教导啊。五天以后天亮时，和我在这里见面。」",
