    id: "chengyu-cy-238",
    title: "一饭千金",
    entries: ["chengyu-cy-238"],
    text: "信钓于城下，诸母漂，有一母见信饥，饭信，竟漂数十日。信喜，谓漂母曰：「吾必有以重报母。」……信至国，召所从食漂母，赐千金。",
    translation: "韩信在城下钓鱼，有几位妇女漂洗衣物，其中一位妇女见韩信饥饿，就拿饭给他吃，一直漂洗了几十天。韩信很高兴，对那位妇女说：「我将来一定要重重地报答您。」……韩信到了自己的封国，召来当年给他饭吃的那位妇女，赐给她千金。",
