    title: "多多益善",
    entries: ["chengyu-cy-239"],
    text: "上问曰：「如我能将几何？」信曰：「陛下不过能将十万。」上曰：「于君何如？」曰：「臣多多而益善耳。」",
    translation: "皇上问：「像我能统率多少兵？」韩信说：「陛下不过能统率十万。」皇上说：「那对你怎么样？」韩信说：「我越多越好。」",
    translationSource: "public-domain",
    version: "88czkn"
