    entries: ["chengyu-cy-25"],
    text: "楚有养由基者，善射者也。去柳叶百步而射之，百发而百中之。左右观者数千人，皆曰善射。",
    translation: "楚国有个叫养由基的人，是善于射箭的人。他离开柳叶一百步射它，射一百次中一百次。旁边围观的有几千人，都说他射得好。",
