    translation: "（匈奴）于是把苏武迁到北海边荒无人烟的地方，让他放牧公羊，说等公羊生了小羊才放他回去。……苏武到了北海之上，官府供给的粮食不到，就挖野鼠、收草籽来吃。他拄着汉朝的符节放羊，睡下起来都拿着，节上的旄尾都脱落了。",
