    entries: ["chengyu-cy-298"],
    text: "异朝京师。引见，帝谓公卿曰：「是我起兵时主簿也。为吾披荆棘，定关中。」",
    translation: "冯异到京城朝见。光武帝接见他，对公卿们说：「这是我起兵时的主簿。为我披荆斩棘、平定了关中。」",
