    title: "举案齐眉",
    entries: ["chengyu-cy-303"],
    text: "遂至吴，依大家皋伯通，居庑下，为人赁舂。每归，妻为具食，不敢于鸿前仰视，举案齐眉。",
    translation: "（梁鸿）于是到了吴地，依附大户人家皋伯通，住在廊下，替人舂米。每次回来，妻子为他准备好食物，不敢在梁鸿面前仰视，把托盘举得和眉毛齐平。",
