    text: "诸将见战陈不利，或多惶惧，失其常度。汉意气自若，方整厉器械，激扬士吏。帝时遣人观大司马何为，还言方修战攻之具，乃叹曰：「吴公差强人意，隐若一敌国矣！」",
    translation: "众将见战事不利，有的惶恐畏惧，失去了常态。吴汉却意气自若，正在整饬器械、激励将士。皇帝当时派人去看大司马在做什么，回报说他正在修整作战进攻的器具，于是感叹说：「吴公还算能让人满意，威严得像一个敌国。」",
