    translation: "堵塞百姓的嘴，比堵塞河流还要危险。河流被堵塞而一旦崩溃，伤害的人一定很多，百姓也是如此。所以治水的人要疏通河道让水畅流，治理百姓的人要开导他们让他们说话。",
