    title: "烽火戏诸侯",
    entries: ["chengyu-cy-33"],
    text: "褒姒不好笑，幽王欲其笑万方，故不笑。幽王为烽燧大鼓，有寇至则举烽火。诸侯悉至，至而无寇，褒姒乃大笑。幽王说之，为数举烽火。其后不信，诸侯益亦不至。",
    translation: "褒姒不爱笑，周幽王想尽办法要她笑，她却始终不笑。幽王设置了烽火和战鼓，有敌寇来就举起烽火。诸侯们全都赶来，到了却没有敌寇，褒姒这才大笑。幽王很高兴，为她多次点起烽火。此后诸侯不再相信，也就渐渐不来了。",
