    title: "老牛舐犊",
    entries: ["chengyu-cy-332"],
    text: "子修为曹操所杀。操见彪问曰：「公何瘦之甚？」对曰：「愧无日磾先见之明，犹怀老牛舐犊之爱。」",
    translation: "杨修被曹操杀害。曹操见到杨彪问他：「您怎么瘦得这么厉害？」杨彪回答说：「我惭愧没有金日磾那样先见之明，却还怀着老牛舐犊的爱子之情。」",
