    title: "车载斗量",
    entries: ["chengyu-cy-333"],
    text: "魏文帝善之，嘲咨曰：「吴如大夫者几人？」咨曰：「聪明特达者八九十人，如臣之比，车载斗量，不可胜数。」",
    translation: "（赵咨出使魏国）魏文帝欣赏他，嘲笑赵咨说：「吴国像大夫这样的人有几个？」赵咨说：「聪明通达的有八九十人，像我这样的人，用车子装、用斗量，数都数不过来。」",
