    entries: ["chengyu-cy-338"],
    text: "司马文王与禅宴，为之作故蜀技，旁人皆为之感怆，而禅喜笑自若。……王曰：「何乃似郤正语邪！」禅惊视曰：「诚如尊命。」左右皆笑。他日，王问禅曰：「颇思蜀否？」禅曰：「此间乐，不思蜀。」",
    translation: "司马昭与刘禅宴饮，为他演奏蜀地的旧乐，旁边的人都为他感伤，而刘禅却嬉笑自如。……司马昭说：「怎么竟像郤正说的话呢！」刘禅吃惊地看着说：「确实像您说的那样。」左右的人都笑了。另一天，司马昭问刘禅说：「很想念蜀地吗？」刘禅说：「这里快乐，不想蜀地。」",
