    entries: ["chengyu-cy-340"],
    text: "文帝尝令东阿王七步中作诗，不成者行大法。应声便为诗曰：「煮豆持作羹，漉菽以为汁。萁在釜下然，豆在釜中泣。本自同根生，相煎何太急？」",
    translation: "魏文帝曾经命令东阿王曹植在七步之内作一首诗，作不成就处以大刑。曹植应声就作诗说：「煮豆拿来作羹，滤去豆渣做成汁。豆萁在锅下燃烧，豆子在锅里哭泣。本来是同一条根上生长出来的，为什么要这样急迫地煎熬我呢？」",
