    title: "草木皆兵",
    entries: ["chengyu-cy-372"],
    text: "坚与苻融登城而望王师，见部阵齐整，将士精锐；又北望八公山上草木，皆类人形，顾谓融曰：「此亦勍敌也，何谓少乎！」怃然有惧色。",
    translation: "苻坚与苻融登上城楼眺望晋军，看见军队阵容整齐、将士精锐；又向北望见八公山上的草木，都像人的形状，回头对苻融说：「这也是强劲的敌手啊，怎么能说少呢！」于是神情失意、面有惧色。",
