    text: "俄而雪骤，公欣然曰：「白雪纷纷何所似？」兄子胡儿曰：「撒盐空中差可拟。」兄女曰：「未若柳絮因风起。」公大笑乐。",
    translation: "不一会儿雪下得急了，谢安兴致勃勃地说：「白雪纷纷扬扬像什么呢？」侄子谢朗说：「像把盐撒在空中，大致可以相比。」侄女谢道韫说：「不如比作柳絮乘风而起。」谢安大笑，非常高兴。",
