    text: "郗太傅在京口，遣门生与王丞相书，求女婿。……门生归白郗曰：「王家诸郎亦皆可嘉，闻来觅婿，咸自矜持，唯有一郎在东床上坦腹卧，如不闻。」郗公云：「正此好！」访之，乃是逸少，因嫁女与焉。",
