    translation: "到了尧的时候，十个太阳一同出来，晒焦了庄稼，枯死了草木，百姓没有东西可吃。猰貐、凿齿、九婴、大风、封豨、修蛇，都为害百姓。尧就派后羿在畴华的原野上杀死凿齿，在凶水边上杀死九婴，在青丘的沼泽中射落大风，向上射下十个太阳，向下杀死猰貐，在洞庭斩断修蛇，在桑林活捉封豨。万民欢喜，拥戴尧做天子。",
