    translation: "陈朝太子舍人徐德言的妻子，是后主陈叔宝的妹妹，封为乐昌公主，才貌冠绝当世。……徐德言对妻子说：「凭你的才华容貌，国家灭亡后一定会落入权贵豪族之家，这就永远断绝了。倘若情缘未断，还希望相见，应该留个信物。」于是打破一面镜子，两人各拿一半，约定说：「将来一定要在正月十五那天在都市上卖，我如果还在，就在那一天去寻访。」",
