    title: "黔驴技穷",
    entries: ["chengyu-cy-430"],
    text: "黔无驴，有好事者船载以入。至则无可用，放之山下。虎见之，庞然大物也，以为神，蔽林间窥之。稍出近之，憖憖然，莫相知。他日，驴一鸣，虎大骇，远遁；以为且噬己也，甚恐。然往来视之，觉无异能者……益狎，荡倚冲冒。驴不胜怒，蹄之。虎因喜，计之曰：「技止此耳！」因跳踉大㘎，断其喉，尽其肉，乃去。",
    translation: "贵州本来没有驴，有个好事的人用船运了一头进去。运到后却没有什么用处，就把它放在山下。老虎看见它，是个庞然大物，以为是神，躲在树林里偷偷地看它。渐渐地走出来接近它，小心谨慎地，不知道它是什么东西。有一天，驴叫了一声，老虎大为惊恐，远远地逃开，以为它要咬自己，非常害怕。然而来回观察它，觉得它并没有什么特殊的本领……就更加靠近它，碰一碰、靠一靠、冲撞冒犯它。驴非常愤怒，就踢了老虎一脚。老虎于是高兴起来，心里盘算着说：「它的本领不过如此罢了！」于是跳起来大吼一声，咬断它的喉咙，吃光它的肉，才离去。",
