    entries: ["chengyu-cy-44"],
    text: "公与之乘，战于长勺。公将鼓之。刿曰：「未可。」齐人三鼓。刿曰：「可矣。」齐师败绩。公将驰之。刿曰：「未可。」下视其辙，登轼而望之，曰：「可矣。」遂逐齐师。既克，公问其故。对曰：「夫战，勇气也。一鼓作气，再而衰，三而竭。彼竭我盈，故克之。」",
    translation: "鲁庄公和曹刿同乘一辆战车，在长勺与齐军交战。庄公将要击鼓进军，曹刿说：「还不行。」齐军三次击鼓之后，曹刿说：「可以了。」齐军大败。庄公将要追击，曹刿说：「还不行。」他下车察看齐军车轮的痕迹，又登上车前横木远望齐军，说：「可以了。」于是追击齐军。战胜之后，庄公问他取胜的缘故。曹刿回答说：「作战，靠的是勇气。第一次击鼓振作士气，第二次击鼓士气就衰减了，第三次击鼓士气就枯竭了。敌军士气枯竭而我军士气饱满，所以能战胜他们。」",
