    entries: ["chengyu-cy-46"],
    text: "管仲曰：「吾始困时，尝与鲍叔贾，分财利多自与，鲍叔不以我为贪，知我贫也。吾尝为鲍叔谋事而更穷困，鲍叔不以我为愚，知时有利不利也。吾尝三仕三见逐于君，鲍叔不以我为不肖，知我不遭时也。生我者父母，知我者鲍子也。」",
    translation: "管仲说：「我当初困窘时，曾和鲍叔一起做生意，分财利时我常常多拿，鲍叔不认为我贪心，知道我家贫。我曾替鲍叔办事却办得更糟，鲍叔不认为我愚笨，知道时机有顺利有不顺利。我曾三次做官三次被君主罢免，鲍叔不认为我不成材，知道我没有遇上好时机。生我的是父母，了解我的是鲍叔啊。」",
    translationSource: "public-domain",
    version: "16skasp"
