    translation: "到了楚国，楚成王设宴款待他，说：「公子如果回到晋国即位，拿什么报答我呢？」重耳回答说：「男女奴仆、宝玉丝绸，您都有了；鸟羽、兽毛、象牙、皮革，是贵国出产的。那些流散到晋国的，都是您剩余的东西，我拿什么报答您呢？」楚王说：「虽然这样，到底拿什么报答我？」重耳回答说：「如果托您的福，能够回到晋国即位，将来晋、楚两国交战，在中原相遇，我一定退让三舍（九十里）。」",
