    translation: "夜里读孟郊的诗，字细得像牛毛。寒灯照着昏花的眼睛，好句子偶尔才碰到一处。孤零零的香花从荒草里拔出来，苦语中还留着《诗》《骚》的余味。水清石净，急流里撑不进竹篙。起初像吃小鱼，得到的抵不上费的功夫；又像煮小蟹，嚼了一整天只是空壳。论清峻可以比得上诗僧，论豪放却还够不上韩愈。人生像朝露，日夜像火熬油。何苦拿两只耳朵，去听这寒虫的号叫。不如先放下，喝我的美酒。……诗是从肺腑里流出来的，流出来又愁坏了肺腑。",
