    entries: ["chengyu-cy-6"],
    text: "天地混沌如鸡子，盘古生其中。万八千岁，天地开辟，阳清为天，阴浊为地。盘古在其中，一日九变，神于天，圣于地。天日高一丈，地日厚一丈，盘古日长一丈。如此万八千岁，天数极高，地数极深，盘古极长。",
    translation: "天地还没有分开的时候，混沌得像一个鸡蛋，盘古就生在其中。经过了一万八千年，天地分开了，轻清的气上升成为天，重浊的气下沉成为地。盘古在天地之间，一天变化九次，比天还神妙，比地还圣明。天每天升高一丈，地每天加厚一丈，盘古每天也长高一丈。这样过了一万八千年，天升得极高了，地积得极厚了，盘古也长得极高了。",
