    text: "穿封戌囚皇颉，公子围与之争之，正于伯州犁。伯州犁曰：「请问于囚。」乃立囚。伯州犁曰：「所争，君子也，其何不知？」上其手，曰：「夫子为王子围，寡君之贵介弟也。」下其手，曰：「此子为穿封戌，方城外之县尹也。谁获子？」囚曰：「颉遇王子，弱焉。」",
    translation: "穿封戌俘虏了皇颉，公子围和他争夺这个功劳，让伯州犁来评判。伯州犁说：「请问问这个俘虏。」于是把俘虏带上来。伯州犁说：「所争的是君子，他有什么不知道的？」他向上抬手说：「这位是王子围，是我们国君尊贵的弟弟。」又向下按手说：「这位是穿封戌，是方城外的县尹。是谁俘虏了你？」俘虏说：「我遇上王子，被他打败了。」",
