    text: "公疾病，求医于秦。秦伯使医缓为之。未至，公梦疾为二竖子，曰：「彼，良医也。惧伤我，焉逃之？」其一曰：「居肓之上，膏之下，若我何？」医至，曰：「疾不可为也，在肓之上，膏之下，攻之不可，达之不及，药不至焉，不可为也。」公曰：「良医也。」厚为之礼而归之。",
    translation: "晋景公生了重病，向秦国求医。秦桓公派医生缓去给他治病。医生还没到，景公梦见疾病变成两个小孩，其中一个说：「那人是个好医生，恐怕会伤害我们，往哪里逃呢？」另一个说：「躲到肓的上面、膏的下面，能把我们怎么样？」医生到了，说：「病已不能治了，在肓的上面、膏的下面，灸治不能攻到，针刺达不到，药力也到不了，不能治了。」景公说：「真是好医生啊。」送给他丰厚的礼物让他回去了。",
