    title: "多行不义必自毙",
    entries: ["chengyu-cy-66"],
    text: "祭仲曰：「都城过百雉，国之害也。先王之制：大都，不过参国之一；中，五之一；小，九之一。今京不度，非制也，君将不堪。」公曰：「姜氏欲之，焉辟害？」对曰：「姜氏何厌之有？不如早为之所，无使滋蔓！蔓，难图也。蔓草犹不可除，况君之宠弟乎？」公曰：「多行不义，必自毙，子姑待之。」",
    translation: "祭仲说：「都城超过三百丈，是国家的祸害。先王的制度：大的都城不超过国都的三分之一，中等的不超过五分之一，小的不超过九分之一。如今京邑的规模不合规定，不是先王的制度，您会受不了的。」庄公说：「姜氏想要这样，怎么能够躲避祸害？」祭仲回答说：「姜氏哪里有满足的时候？不如及早给她安排个地方，不要让她的势力滋长蔓延！一旦蔓延开来，就难以对付了。蔓草尚且不能除掉，何况是您那受宠的弟弟呢？」庄公说：「多做不义的事，一定会自取灭亡，你姑且等着看吧。」",
    translationSource: "public-domain",
    version: "sg460y"
