    text: "公宴于五梧，武伯为祝，恶郭重，曰：「何肥也？」季孙曰：「请饮彘也！以鲁国之密迩仇雠，臣是以不获从君，克免于大行，又谓重也肥。」公曰：「是食言多矣，能无肥乎？」",
