    text: "是故圣人不治已病治未病，不治已乱治未乱，此之谓也。夫病已成而后药之，乱已成而后治之，譬犹渴而穿井，斗而铸锥，不亦晚乎！",
    translation: "所以圣人不治已经发生的病而治尚未发生的病，不治已经发生的乱而治尚未发生的乱，说的就是这个道理。等到病已经形成才去用药，乱已经形成才去治理，就好比渴了才去挖井、临阵才去铸造兵器，不是太晚了吗！",
