    text: "夏，齐孝公伐我北鄙。……公使展喜犒师，使受命于展禽。齐侯未入竟，展喜从之，曰：「寡君闻君亲举玉趾，将辱于敝邑，使下臣犒执事。」齐侯曰：「鲁人恐乎？」对曰：「小人恐矣，君子则否。」齐侯曰：「室如县罄，野无青草，何恃而不恐？」对曰：「恃先王之命。……」",
