    entries: ["chengyu-cy-478", "classic-gw-244"],
    text: "有《早梅》诗曰：「前村深雪里，昨夜数枝开。」谷曰：「数枝非早也，未若一枝佳。」齐己不觉投拜曰：「我一字师也。」",
    translation: "（齐己）有《早梅》诗说：「前村深雪里，昨夜数枝开。」郑谷说：「『数枝』不算早，不如『一枝』更好。」齐己不由得叩拜说：「您真是我的一字之师啊。」",
