    text: "慈母手中线，游子身上衣。\n临行密密缝，意恐迟迟归。\n谁言寸草心，报得三春晖。",
    translation: "慈爱的母亲手里拿着针线，为将要远行的儿子缝制衣服。临行前密密地缝了又缝，担心孩子迟迟不能回来。谁说小草一样微薄的心意，能报答得了春天阳光般的恩情？",
